arguments.script:
hhmm = lambda t: frappe.utils.format_datetime(t, "HH:mm")
talks = {}
for s in frappe.get_all("Session", filters={"status": ["!=", "Cancelled"]}, fields=["speaker", "session_title", "day", "room", "start_time", "end_time"], order_by="start_time asc"):
    if s.speaker and s.speaker not in talks:
        talks[s.speaker] = s
speakers = frappe.get_all("Speaker", fields=["name", "full_name", "company", "designation", "city", "country", "bio"], order_by="full_name asc")
out = []
for s in speakers:
    parts = s.full_name.split()
    t = talks.get(s.name)
    out.append({
        "full_name": s.full_name,
        "initials": (parts[0][0] + parts[-1][0]).upper(),
        "role": f"{s.designation}, {s.company}" if s.designation else (s.company or ""),
        "place": ", ".join([p for p in [s.city, s.country] if p]),
        "bio": s.bio or "",
        "talk": t.session_title if t else "Talk to be announced",
        "when": f"{t.day.upper()} · {hhmm(t.start_time)}–{hhmm(t.end_time)} · {t.room.upper()}" if t else "SCHEDULE",
    })
data.speakers = out

