arguments.script:
accepted = frappe.get_all("Talk Proposal", filters={"status": "Accepted", "speaker": ["is", "set"]}, fields=["speaker", "title"], order_by="title asc")
talks = {}
for p in accepted:
    if p.speaker not in talks:
        talks[p.speaker] = p.title
speakers = frappe.get_all("Speaker", filters={"name": ["in", list(talks.keys()) or ["-"]]}, fields=["name", "full_name", "company"], order_by="full_name asc")
out = []
for s in speakers:
    parts = s.full_name.split()
    out.append({
        "full_name": s.full_name,
        "company": s.company or "",
        "initials": (parts[0][0] + parts[-1][0]).upper(),
        "talk": talks.get(s.name, ""),
    })
data.speakers = out

sponsors = frappe.get_all("Sponsor", filters={"stage": ["in", ["Committed", "Paid"]]}, fields=["company_name", "tier", "logo"], order_by="company_name asc")
for s in sponsors:
    s.mark = f'<img src="{s.logo}" alt="{s.company_name}" style="height:44px;display:block">' if s.logo else s.company_name
data.platinum = [s for s in sponsors if s.tier == "Platinum"]
data.gold = [s for s in sponsors if s.tier == "Gold"]
data.silver = [s for s in sponsors if s.tier == "Silver"]
data.community = [s for s in sponsors if s.tier == "Community"]

