blocks = frappe.parse_json(frappe.get_doc("Builder Page", "page-b907221b")["draft_blocks"])
found = []
def walk(b):
    if b.get("blockName") in ("Tab Styles", "Day 1 Radio", "Day 2 Radio", "Tab List", "Day 1 Panel", "Day 2 Panel"):
        found.append({"name": b.get("blockName"), "element": b.get("element"), "classes": b.get("classes"), "attrs": b.get("attributes"), "text": (b.get("innerHTML") or "")[:60]})
    for c in b.get("children") or []:
        walk(c)
for b in blocks:
    walk(b)
result = found

values.script:
if frappe.session.user == "Guest":
    if not doc.email:
        frappe.throw("Please add your email so we can send your ticket.")
    if not doc.ticket_type:
        frappe.throw("Please choose a ticket.")
    if doc.ticket_type in ("Speaker", "Sponsor Pass"):
        frappe.throw("Speaker and sponsor passes are issued by the Frappeverse team. Please choose Early Bird, Standard, Late or Student.")
    doc.conference = "Frappeverse 2027"
    doc.checked_in = 0

# Payments are out of scope: every new registration is Paid at its ticket's price.
if not doc.conference:
    doc.conference = "Frappeverse 2027"
if not doc.registered_on:
    doc.registered_on = frappe.utils.today()
if doc.ticket_type:
    doc.amount_paid = frappe.db.get_value("Ticket Type", doc.ticket_type, "price") or 0
    doc.payment_status = "Paid"

records.script:
if not doc.ticket_code:
    code = "FV27-" + frappe.generate_hash(length=6).upper()
    while frappe.db.exists("Attendee", {"ticket_code": code}):
        code = "FV27-" + frappe.generate_hash(length=6).upper()
    doc.ticket_code = code

