pages = ["page-8a78e00f", "page-b907221b", "page-1e6b7d3c", "page-e730b422", "page-c233ccf4"]
out = {}
for p in pages:
    d = frappe.get_doc("Builder Page", p)
    src = d.get("draft_blocks") or d.get("blocks")
    n = src.count("/frappeverse/call-for-talks")
    if n:
        r = update("Builder Page", [p], {"draft_blocks": src.replace("/frappeverse/call-for-talks", "/frappeverse/submit-talk")})
        out[p] = r.get("failures") or n
    else:
        out[p] = 0
result = out

